            bytes32 salt = _salt(_saltBytes, i, msg.sender);
            address proxy = _deployProxy(salt);

            // Call proxy with the provided calldata (no assembly)
            // (ignore success to match original behavior)
            proxy.call(data);
        }

        map[msg.sender][_saltBytes] += total;
    }

