        view
        returns (TCBLevelsObj[] memory, TDXModule memory, TDXModuleIdentity[] memory);

    function getFmspcTcbContentHash(TcbId id, bytes6 fmspc, uint32 version) external view returns (bytes32);

    function getPckCert(
