pragma solidity ^0.8.0;

// Inspired by ensdomains/dnssec-oracle - BSD-2-Clause license
// https://github.com/ensdomains/dnssec-oracle/blob/master/contracts/BytesUtils.sol

library BytesUtils {
    /*
    * @dev Returns the keccak-256 hash of a byte range.
    * @param self The byte string to hash.
    * @param offset The position to start hashing at.
    * @param len The number of bytes to hash.
    * @return The hash of the byte range.
    */
    function keccak(bytes memory self, uint256 offset, uint256 len) internal pure returns (bytes32 ret) {
        require(offset + len <= self.length);
        assembly {
            ret := keccak256(add(add(self, 32), offset), len)
        }
    }

    /*
    * @dev Returns a positive number if `other` comes lexicographically after
    *      `self`, a negative number if it comes before, or zero if the
    *      contents of the two bytes are equal.
    * @param self The first bytes to compare.
    * @param other The second bytes to compare.
    * @return The result of the comparison.
    */
    function compare(bytes memory self, bytes memory other) internal pure returns (int256) {
        return compare(self, 0, self.length, other, 0, other.length);
    }

    /*
    * @dev Returns a positive number if `other` comes lexicographically after
    *      `self`, a negative number if it comes before, or zero if the
    *      contents of the two bytes are equal. Comparison is done per-rune,
    *      on unicode codepoints.
    * @param self The first bytes to compare.
    * @param offset The offset of self.
    * @param len    The length of self.
    * @param other The second bytes to compare.
    * @param otheroffset The offset of the other string.
    * @param otherlen    The length of the other string.
    * @return The result of the comparison.
    */
    function compare(
        bytes memory self,
        uint256 offset,
        uint256 len,
        bytes memory other,
        uint256 otheroffset,
        uint256 otherlen
    ) internal pure returns (int256) {
        uint256 shortest = len;
        if (otherlen < len) {
            shortest = otherlen;
        }

        uint256 selfptr;
        uint256 otherptr;

        assembly {
            selfptr := add(self, add(offset, 32))
            otherptr := add(other, add(otheroffset, 32))
        }
        for (uint256 idx = 0; idx < shortest; idx += 32) {
            uint256 a;
            uint256 b;
            assembly {
                a := mload(selfptr)
                b := mload(otherptr)
            }
            if (a != b) {
                // Mask out irrelevant bytes and check again
                uint256 mask;
                if (shortest > 32) {
                    mask = type(uint256).max; // aka 0xffffff....
                } else {
                    mask = ~(2 ** (8 * (32 - shortest + idx)) - 1);
                }
                uint256 diff = (a & mask) - (b & mask);
                if (diff != 0) {
                    return int256(diff);
                }
            }
            selfptr += 32;
            otherptr += 32;
        }

        return int256(len) - int256(otherlen);
    }

    /*
    * @dev Returns true if the two byte ranges are equal.
    * @param self The first byte range to compare.
    * @param offset The offset into the first byte range.
    * @param other The second byte range to compare.
    * @param otherOffset The offset into the second byte range.
    * @param len The number of bytes to compare
    * @return True if the byte ranges are equal, false otherwise.
    */
    function equals(bytes memory self, uint256 offset, bytes memory other, uint256 otherOffset, uint256 len)
        internal
        pure
        returns (bool)
    {
        return keccak(self, offset, len) == keccak(other, otherOffset, len);
    }

    /*
    * @dev Returns true if the two byte ranges are equal with offsets.
    * @param self The first byte range to compare.
    * @param offset The offset into the first byte range.
    * @param other The second byte range to compare.
    * @param otherOffset The offset into the second byte range.
    * @return True if the byte ranges are equal, false otherwise.
    */
    function equals(bytes memory self, uint256 offset, bytes memory other, uint256 otherOffset)
        internal
        pure
        returns (bool)
    {
        return keccak(self, offset, self.length - offset) == keccak(other, otherOffset, other.length - otherOffset);
    }

    /*
    * @dev Compares a range of 'self' to all of 'other' and returns True iff
    *      they are equal.
    * @param self The first byte range to compare.
    * @param offset The offset into the first byte range.
    * @param other The second byte range to compare.
    * @return True if the byte ranges are equal, false otherwise.
    */
    function equals(bytes memory self, uint256 offset, bytes memory other) internal pure returns (bool) {
        return self.length >= offset + other.length && equals(self, offset, other, 0, other.length);
    }

    /*
    * @dev Returns true if the two byte ranges are equal.
    * @param self The first byte range to compare.
    * @param other The second byte range to compare.
    * @return True if the byte ranges are equal, false otherwise.
    */
    function equals(bytes memory self, bytes memory other) internal pure returns (bool) {
        return self.length == other.length && equals(self, 0, other, 0, self.length);
    }

    /*
    * @dev Returns the 8-bit number at the specified index of self.
    * @param self The byte string.
    * @param idx The index into the bytes
    * @return The specified 8 bits of the string, interpreted as an integer.
    */
    function readUint8(bytes memory self, uint256 idx) internal pure returns (uint8 ret) {
        return uint8(self[idx]);
    }

    /*
    * @dev Returns the 16-bit number at the specified index of self.
    * @param self The byte string.
    * @param idx The index into the bytes
    * @return The specified 16 bits of the string, interpreted as an integer.
    */
    function readUint16(bytes memory self, uint256 idx) internal pure returns (uint16 ret) {
        require(idx + 2 <= self.length);
        assembly {
            ret := and(mload(add(add(self, 2), idx)), 0xFFFF)
        }
    }

    /*
    * @dev Returns the 32-bit number at the specified index of self.
    * @param self The byte string.
    * @param idx The index into the bytes
    * @return The specified 32 bits of the string, interpreted as an integer.
    */
    function readUint32(bytes memory self, uint256 idx) internal pure returns (uint32 ret) {
        require(idx + 4 <= self.length);
        assembly {
            ret := and(mload(add(add(self, 4), idx)), 0xFFFFFFFF)
        }
    }

    /*
    * @dev Returns the 32 byte value at the specified index of self.
    * @param self The byte string.
    * @param idx The index into the bytes
    * @return The specified 32 bytes of the string.
    */
    function readBytes32(bytes memory self, uint256 idx) internal pure returns (bytes32 ret) {
        require(idx + 32 <= self.length);
        assembly {
            ret := mload(add(add(self, 32), idx))
        }
    }

    /*
    * @dev Returns the 32 byte value at the specified index of self.
    * @param self The byte string.
    * @param idx The index into the bytes
    * @return The specified 32 bytes of the string.
    */
    function readBytes20(bytes memory self, uint256 idx) internal pure returns (bytes20 ret) {
        require(idx + 20 <= self.length);
        assembly {
            ret :=
                and(mload(add(add(self, 32), idx)), 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF000000000000000000000000)
        }
    }

    /*
    * @dev Returns the n byte value at the specified index of self.
    * @param self The byte string.
    * @param idx The index into the bytes.
    * @param len The number of bytes.
    * @return The specified 32 bytes of the string.
    */
    function readBytesN(bytes memory self, uint256 idx, uint256 len) internal pure returns (bytes32 ret) {
        require(len <= 32);
        require(idx + len <= self.length);
        assembly {
            let mask := not(sub(exp(256, sub(32, len)), 1))
            ret := and(mload(add(add(self, 32), idx)), mask)
        }
    }

    function memcpy(uint256 dest, uint256 src, uint256 len) private pure {
        // Copy word-length chunks while possible
        for (; len >= 32; len -= 32) {
            assembly {
                mstore(dest, mload(src))
            }
            dest += 32;
            src += 32;
        }

        // Copy remaining bytes
        uint256 mask;
        if (len == 0) {
            mask = type(uint256).max; // Set to maximum value of uint256
        } else {
            mask = 256 ** (32 - len) - 1;
        }

        assembly {
            let srcpart := and(mload(src), not(mask))
            let destpart := and(mload(dest), mask)
            mstore(dest, or(destpart, srcpart))
        }
    }

    /*
    * @dev Copies a substring into a new byte string.
    * @param self The byte string to copy from.
    * @param offset The offset to start copying at.
    * @param len The number of bytes to copy.
    */
    function substring(bytes memory self, uint256 offset, uint256 len) internal pure returns (bytes memory) {
        require(offset + len <= self.length);

        bytes memory ret = new bytes(len);
        uint256 dest;
        uint256 src;

        assembly {
            dest := add(ret, 32)
            src := add(add(self, 32), offset)
        }
        memcpy(dest, src, len);

        return ret;
    }

    // Maps characters from 0x30 to 0x7A to their base32 values.
    // 0xFF represents invalid characters in that range.
    bytes constant base32HexTable =
        hex"00010203040506070809FFFFFFFFFFFFFF0A0B0C0D0E0F101112131415161718191A1B1C1D1E1FFFFFFFFFFFFFFFFFFFFF0A0B0C0D0E0F101112131415161718191A1B1C1D1E1F";

    /**
     * @dev Decodes unpadded base32 data of up to one word in length.
     * @param self The data to decode.
     * @param off Offset into the string to start at.
     * @param len Number of characters to decode.
     * @return The decoded data, left aligned.
     */
    function base32HexDecodeWord(bytes memory self, uint256 off, uint256 len) internal pure returns (bytes32) {
        require(len <= 52);

        uint256 ret = 0;
        uint8 decoded;
        for (uint256 i = 0; i < len; i++) {
            bytes1 char = self[off + i];
            require(char >= 0x30 && char <= 0x7A);
            decoded = uint8(base32HexTable[uint256(uint8(char)) - 0x30]);
            require(decoded <= 0x20);
            if (i == len - 1) {
                break;
            }
            ret = (ret << 5) | decoded;
        }

        uint256 bitlen = len * 5;
        if (len % 8 == 0) {
            // Multiple of 8 characters, no padding
            ret = (ret << 5) | decoded;
        } else if (len % 8 == 2) {
            // Two extra characters - 1 byte
            ret = (ret << 3) | (decoded >> 2);
            bitlen -= 2;
        } else if (len % 8 == 4) {
            // Four extra characters - 2 bytes
            ret = (ret << 1) | (decoded >> 4);
            bitlen -= 4;
        } else if (len % 8 == 5) {
            // Five extra characters - 3 bytes
            ret = (ret << 4) | (decoded >> 1);
            bitlen -= 1;
        } else if (len % 8 == 7) {
            // Seven extra characters - 4 bytes
            ret = (ret << 2) | (decoded >> 3);
            bitlen -= 3;
        } else {
            revert();
        }

        return bytes32(ret << (256 - bitlen));
    }

    function compareBytes(bytes memory a, bytes memory b) internal pure returns (bool) {
        if (a.length != b.length) {
            return false;
        }
        for (uint256 i = 0; i < a.length; i++) {
            if (a[i] != b[i]) {
                return false;
            }
        }
        return true;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {Ownable} from "solady/auth/Ownable.sol";
import "dcap-attestation/types/Constants.sol";
import {BytesUtils} from "dcap-attestation/utils/BytesUtils.sol";
// import "forge-std/console.sol";

contract MeasurementDao is Ownable {
    using BytesUtils for bytes;

    mapping(bytes32 => bytes32) private mr;
    bytes32[] private mrEnclaveList;
    mapping(bytes => bool) private rtmr;
    bytes[] private rtmrList;

    mapping(bytes => bool) private mrtdMap;
    bytes[] private mrtdList;

    uint16 private constant MR_ENCLAVE_OFFSET = 112;
    uint16 private constant MR_SIGNER_OFFSET = 176;

    error AlreadyExists();
    error NotExists();

    constructor() {
        _initializeOwner(msg.sender);
    }

    /**
     * @notice
     * @param _mrEnclave measurement of enclave
     * @param _mrSigner measurement of signer
     */
    function add_mr_enclave(bytes32 _mrEnclave, bytes32 _mrSigner) external onlyOwner {
        if (mr[_mrEnclave] != bytes32(0)) revert AlreadyExists();
        mr[_mrEnclave] = _mrSigner;
        mrEnclaveList.push(_mrEnclave);
    }

    /**
     * @notice
     * @param _mrEnclave measurement of enclave
     */
    function delete_mr_enclave(bytes32 _mrEnclave) external onlyOwner {
        if (mr[_mrEnclave] == bytes32(0)) revert NotExists();
        delete mr[_mrEnclave];
        for (uint256 i = 0; i < mrEnclaveList.length; ++i) {
            if (mrEnclaveList[i] == _mrEnclave) {
                mrEnclaveList[i] = mrEnclaveList[mrEnclaveList.length - 1];
                mrEnclaveList.pop();
                break;
            }
        }
    }

    function get_mr_enclave() external view returns (bytes32[] memory) {
        return mrEnclaveList;
    }

    function clearup_mr_enclave() external onlyOwner {
        for (uint256 i = 0; i < mrEnclaveList.length; ++i) {
            delete mr[mrEnclaveList[i]];
        }
        delete mrEnclaveList;
    }

    /**
     * @notice
     * @param rtmr3
     */
    function add_rtMr(bytes calldata rtmr3) external onlyOwner {
        if (rtmr[rtmr3]) revert AlreadyExists();
        rtmr[rtmr3] = true;
        rtmrList.push(rtmr3);
    }

    /**
     * @notice
     * @param rtmr3
     */
    function delete_rtMr(bytes calldata rtmr3) external onlyOwner {
        if (!rtmr[rtmr3]) revert NotExists();
        delete rtmr[rtmr3];
        bytes32 rtmrHash = keccak256(rtmr3);
        for (uint256 i = 0; i < rtmrList.length; ++i) {
            if (keccak256(rtmrList[i]) == rtmrHash) {
                rtmrList[i] = rtmrList[rtmrList.length - 1];
                rtmrList.pop();
                break;
            }
        }
    }

    function get_rtMr() external view returns (bytes[] memory) {
        return rtmrList;
    }

    function clearup_rtMr() external onlyOwner {
        for (uint256 i = 0; i < rtmrList.length; ++i) {
            delete rtmr[rtmrList[i]];
        }
        delete rtmrList;
    }

    function add_mrtd(bytes calldata mrtd) external onlyOwner {
        if (mrtdMap[mrtd]) revert AlreadyExists();
        mrtdMap[mrtd] = true;
        mrtdList.push(mrtd);
    }

    function delete_mrtd(bytes calldata mrtd) external onlyOwner {
        if (!mrtdMap[mrtd]) revert NotExists();
        delete mrtdMap[mrtd];
        bytes32 mrtdHash = keccak256(mrtd);
        for (uint256 i = 0; i < mrtdList.length; ++i) {
            if (keccak256(mrtdList[i]) == mrtdHash) {
                mrtdList[i] = mrtdList[mrtdList.length - 1];
                mrtdList.pop();
                break;
            }
        }
    }

    function get_mrtd() external view returns (bytes[] memory) {
        return mrtdList;
    }

    function clearup_mrtd() external onlyOwner {
        for (uint256 i = 0; i < mrtdList.length; ++i) {
            delete mrtdMap[mrtdList[i]];
        }
        delete mrtdList;
    }

    function verifyMeasurementSGX(bytes calldata quote, uint16 quoteVersion) external view returns (bool) {
        uint256 mrEnclaveOffset;
        uint256 mrSignerOffset;
        if (quoteVersion == 3) {
            mrEnclaveOffset = MR_ENCLAVE_OFFSET;
            mrSignerOffset = MR_SIGNER_OFFSET;
        } else if (quoteVersion == 4) {
            mrEnclaveOffset = HEADER_LENGTH + 64;
            mrSignerOffset = HEADER_LENGTH + 128;
        } else if (quoteVersion == 5) {
            return false; // quotev5 not support sgx
        } else {
            return false;
        }

        bytes32 mrEnclave = bytes32(quote.substring(mrEnclaveOffset, 32));
        bytes32 mrSigner = bytes32(quote.substring(mrSignerOffset, 32));
        return mrSigner != bytes32(0) && mr[mrEnclave] == mrSigner; //mrSigner not zero
    }

    function verifyMeasurementTDX(bytes calldata quote, uint16 quoteVersion) external view returns (bool) {
        uint256 rtmr3Offset;

        if (quoteVersion == 3) {
            return false; // quotev3 not support tdx
        } else if (quoteVersion == 4) {
            rtmr3Offset = HEADER_LENGTH + 472;
        } else if (quoteVersion == 5) {
            rtmr3Offset = HEADER_LENGTH + 6 + 472;
        } else {
            return false;
        }

        bytes memory rtmr3 = quote.substring(rtmr3Offset, 48);
        return rtmr[rtmr3];
    }

    function verifyMRTD(bytes calldata quote, uint16 quoteVersion) external view returns (bool) {
        uint256 mrtdOffset;

        if (quoteVersion == 3) {
            return false; // quotev3 not support tdx
        } else if (quoteVersion == 4) {
            mrtdOffset = HEADER_LENGTH + 136;
        } else if (quoteVersion == 5) {
            mrtdOffset = HEADER_LENGTH + 6 + 136;
        } else {
            return false;
        }

        bytes memory mrtd = quote.substring(mrtdOffset, 48);
        return mrtdMap[mrtd];
    }
}

