// src/W3S.sol

/**
 * @title W3S - Web3 Summit 2026 Ticketing System
 * @notice ERC721 ticket system with DOT payment, whitelist, and role-based access
 */
contract W3S is ERC721, AccessControl {
    // ============ Enums ============

    enum TicketType { Standard, Free }

    // ============ Constants ============

    bytes32 public constant W3F = keccak256("W3F");
    bytes32 public constant VOLUNTEER = keccak256("VOLUNTEER");

    // ============ State Variables ============

    uint256 private _nextTokenId = 1;

    // Sales control
    bool public salesPaused;

    // Global transfer control
    bool public transfersEnabled;

    // Event metadata
    bytes public eventMetadata;

    // Check-in tracking
    mapping(uint256 => bool) private _checkedIn;

    // Ticket ownership lookup (0 = no ticket, since tokens start at 1)
    mapping(address => uint256) public ticketOf;

    // Ticket type per token
    mapping(uint256 => TicketType) public ticketTypes;

    // Encrypted attendee names (x25519 sealed-box encrypted, keyed by tokenId)
    mapping(uint256 => bytes) public encryptedNames;

    // x25519 public key for name encryption (32 bytes)
    bytes32 public encryptionPublicKey;

    // Ticket price in native DOT (EVM 18-decimal wei)
    uint256 public ticketPrice;

    // Accepted alternative payment tokens (frontend swaps these to DOT via AssetConversion)
    address[] public acceptedTokens;

    // Whitelist mappings
    mapping(address => bool) public isFreeTicket;
    mapping(address => bool) public hasRedeemedFreeTicket;

    // ============ Custom Errors ============

    error TicketDoesNotExist();
    error NotTicketOwner();
    error AlreadyCheckedIn();
    error TransferNotAllowed();
    error SalesPaused();
    error AlreadyHasTicket();
    error EmptyEncryptedName();
    error IncorrectPayment();
    error WithdrawFailed();
    error NothingToWithdraw();
    error NotOnWhitelist();
    error AlreadyRedeemed();

    // ============ Events ============

    event TicketClaimed(uint256 tokenId, address indexed recipient, TicketType ticketType);
    event TicketCheckedIn(uint256 tokenId, address indexed holder, address indexed volunteer);
    event TransfersUpdated(bool enabled);
    event SalesStatusUpdated(bool paused);
    event NameSet(address indexed owner, bytes encryptedName);
    event EncryptionPublicKeyUpdated(bytes32 key);
    event TicketPriceUpdated(uint256 price);
    event AcceptedTokenAdded(address indexed token);
    event AcceptedTokenRemoved(address indexed token);

    // ============ Constructor ============

    constructor(uint256 _ticketPrice, bytes32 _encryptionPublicKey) ERC721("Web3 Summit 2026", "W3S") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _setRoleAdmin(VOLUNTEER, W3F);
        ticketPrice = _ticketPrice;
        encryptionPublicKey = _encryptionPublicKey;
    }

    // ============ External Functions - Ticket Purchase ============

    /**
     * @notice Buy a standard ticket with native DOT
     * @param encryptedName x25519 sealed-box encrypted name bytes
     */
    function buyTicket(bytes calldata encryptedName) external payable {
        if (salesPaused) revert SalesPaused();
        if (balanceOf(msg.sender) > 0) revert AlreadyHasTicket();
        if (encryptedName.length == 0) revert EmptyEncryptedName();
        if (msg.value != ticketPrice) revert IncorrectPayment();

        _mintTicket(msg.sender, TicketType.Standard, encryptedName);
    }

    /**
     * @notice Buy a ticket on behalf of another address (e.g. ephemeral wallet pays, recipient gets the NFT)
     * @param recipient Address that will receive the minted ticket
     * @param encryptedName x25519 sealed-box encrypted name bytes
     */
    function buyTicketFor(address recipient, bytes calldata encryptedName) external payable {
        if (salesPaused) revert SalesPaused();
        if (balanceOf(recipient) > 0) revert AlreadyHasTicket();
        if (encryptedName.length == 0) revert EmptyEncryptedName();
        if (msg.value != ticketPrice) revert IncorrectPayment();

        _mintTicket(recipient, TicketType.Standard, encryptedName);
    }

    /**
     * @notice Redeem a free ticket (must be on free ticket whitelist, no payment)
     * @param encryptedName x25519 sealed-box encrypted name bytes
     */
    function redeemFreeTicket(bytes calldata encryptedName) external {
        if (salesPaused) revert SalesPaused();
        if (!isFreeTicket[msg.sender]) revert NotOnWhitelist();
        if (hasRedeemedFreeTicket[msg.sender]) revert AlreadyRedeemed();
        if (balanceOf(msg.sender) > 0) revert AlreadyHasTicket();
        if (encryptedName.length == 0) revert EmptyEncryptedName();

        hasRedeemedFreeTicket[msg.sender] = true;
        _mintTicket(msg.sender, TicketType.Free, encryptedName);
    }

    /**
     * @notice Burn your own ticket (irreversible)
     * @param tokenId Token ID to burn (must be owned by caller)
     */
    function burnTicket(uint256 tokenId) external {
        address owner = _ownerOf(tokenId);
        if (owner == address(0)) revert TicketDoesNotExist();
        if (owner != msg.sender) revert NotTicketOwner();
        _burn(tokenId);
    }

    // ============ External Functions - Check-in ============

    /**
     * @notice Check in a ticket
     * @param tokenId Token ID to check in
     */
    function checkIn(uint256 tokenId) external onlyRole(VOLUNTEER) {
        if (_ownerOf(tokenId) == address(0)) revert TicketDoesNotExist();
        if (_checkedIn[tokenId]) revert AlreadyCheckedIn();

        address holder = ownerOf(tokenId);
        _checkedIn[tokenId] = true;

        emit TicketCheckedIn(tokenId, holder, msg.sender);
    }

    // ============ External Functions - Admin (W3F) ============

    /**
     * @notice Set event metadata (Gordian Envelope format)
     * @param metadata Event metadata in dCBOR format
     */
    function setEventMetadata(bytes calldata metadata) external onlyRole(W3F) {
        eventMetadata = metadata;
    }

    /**
     * @notice Enable or disable ticket transfers globally
     * @param _enabled Whether tickets can be transferred
     */
    function setTransfersEnabled(bool _enabled) external onlyRole(W3F) {
        transfersEnabled = _enabled;
        emit TransfersUpdated(_enabled);
    }

    /**
     * @notice Enable or disable ticket sales
     * @param _paused Whether sales should be paused
     */
    function setSalesPaused(bool _paused) external onlyRole(W3F) {
        salesPaused = _paused;
        emit SalesStatusUpdated(_paused);
    }

    /**
     * @notice Set the public key used for name encryption
     * @param _key The 32-byte public key
     */
    function setEncryptionPublicKey(bytes32 _key) external onlyRole(DEFAULT_ADMIN_ROLE) {
        encryptionPublicKey = _key;
        emit EncryptionPublicKeyUpdated(_key);
    }

    /**
     * @notice Set the ticket price in native DOT (EVM 18-decimal wei)
     * @param _price Ticket price
     */
    function setTicketPrice(uint256 _price) external onlyRole(W3F) {
        ticketPrice = _price;
        emit TicketPriceUpdated(_price);
    }

    /**
     * @notice Add a token to the accepted payment list
     * @param token ERC20 precompile address on Asset Hub
     */
    function addAcceptedToken(address token) external onlyRole(W3F) {
        acceptedTokens.push(token);
        emit AcceptedTokenAdded(token);
    }

    /**
     * @notice Remove a token from the accepted payment list
     * @param token ERC20 precompile address to remove
     */
    function removeAcceptedToken(address token) external onlyRole(W3F) {
        uint256 len = acceptedTokens.length;
        for (uint256 i = 0; i < len; i++) {
            if (acceptedTokens[i] == token) {
                acceptedTokens[i] = acceptedTokens[len - 1];
                acceptedTokens.pop();
                emit AcceptedTokenRemoved(token);
                return;
            }
        }
    }

    /**
     * @notice Add addresses to free ticket whitelist
     * @param addresses Array of H160 addresses to whitelist
     */
    function addFreeTicketBatch(address[] calldata addresses) external onlyRole(W3F) {
        for (uint256 i = 0; i < addresses.length; i++) {
            isFreeTicket[addresses[i]] = true;
        }
    }

    /**
     * @notice Withdraw accumulated DOT funds (admin only)
     */
    function withdrawFunds() external onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 amount = address(this).balance;
        if (amount == 0) revert NothingToWithdraw();
        (bool success, ) = payable(msg.sender).call{value: amount}("");
        if (!success) revert WithdrawFailed();
    }

    // ============ External Functions - View ============

    /**
     * @notice Check if ticket is checked in
     * @param tokenId Token ID
     * @return True if checked in
     */
    function isCheckedIn(uint256 tokenId) external view returns (bool) {
        if (_ownerOf(tokenId) == address(0)) revert TicketDoesNotExist();
        return _checkedIn[tokenId];
    }

    /**
     * @notice Get total supply of tickets
     * @return Total number of tickets minted
     */
    function totalSupply() public view returns (uint256) {
        return _nextTokenId - 1;
    }

    /**
     * @notice Get all accepted alternative payment tokens
     */
    function getAcceptedTokens() external view returns (address[] memory) {
        return acceptedTokens;
    }

    // ============ Internal Functions ============

    /**
     * @notice Shared minting logic
     */
    function _mintTicket(address to, TicketType ticketType, bytes calldata encryptedName) internal {
        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);

        ticketTypes[tokenId] = ticketType;
        encryptedNames[tokenId] = encryptedName;

        emit TicketClaimed(tokenId, to, ticketType);
        emit NameSet(to, encryptedName);
    }

    /**
     * @notice Override ERC721 transfer to enforce transfer policy and update ticketOf
     */
    function _update(address to, uint256 tokenId, address auth)
        internal
        override
        returns (address)
    {
        address from = _ownerOf(tokenId);

        // For transfers (not minting), check transfer policy and recipient
        if (from != address(0) && to != address(0)) {
            if (!transfersEnabled) revert TransferNotAllowed();
            if (balanceOf(to) > 0) revert AlreadyHasTicket();
        }

        address result = super._update(to, tokenId, auth);

        // Update ticketOf mapping
        if (from != address(0)) {
            delete ticketOf[from];
        }
        if (to != address(0)) {
            ticketOf[to] = tokenId;
        }

        return result;
    }

    // ============ Public Functions ============

    /**
     * @notice Interface support
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

