// src/protocols/poap/IAttendancePOAP.sol

interface IAttendancePOAP {
    struct POAPData {
        address sourceContract;
        address attendee;
        uint64 issuedAt;
    }

    // Minting events
    event POAPMinted(uint256 indexed tokenId, address indexed attendee, address indexed sourceContract);
    event MinterAuthorized(address indexed minter);
    event MinterRevoked(address indexed minter);

    // Factory management events
    event FactoryTransferred(address indexed previousFactory, address indexed newFactory);
    event FactoryRenounced(address indexed previousFactory);

    // Peer verification events
    event PeerVerified(
        address indexed sourceContract,
        address indexed verifier,
        address indexed attendee,
        uint256 verifierTokenId,
        uint256 attendeeTokenId
    );
    event VerificationDeadlineSet(address indexed sourceContract, uint256 deadline);

    // Factory management
    function transferFactory(address newFactory) external;
    function renounceFactory() external;

    // Minter management (factory only)
    function authorizeMinter(address minter) external;
    function revokeMinter(address minter) external;

    // Minting (authorized minters only)
    function mintPOAP(address attendee, address sourceContract) external returns (uint256 tokenId);

    // Peer verification
    function verify(uint256 callerTokenId, uint256 targetTokenId) external;
    function setVerificationDeadline(uint256 deadline) external;

    // Views
    function getPOAPData(uint256 tokenId) external view returns (POAPData memory);
    function getVerificationCount(uint256 tokenId) external view returns (uint256);
    function getHasVerified(uint256 verifierTokenId, uint256 targetTokenId) external view returns (bool);
    function getVerificationDeadline(address sourceContract) external view returns (uint256);
    function getTokensBySource(address sourceContract) external view returns (uint256[] memory);

    // Errors
    error OnlyFactory();
    error OnlyAuthorizedMinter();
    error AlreadyAuthorized();
    error NotAuthorized();
    error SameToken();
    error DifferentSourceContract();
    error SelfVerification();
    error VerificationWindowClosed();
    error AlreadyVerified();
    error DeadlineAlreadySet();
    error DeadlineInPast();
}

